const CATCH_QUOTES={lambari:"Esse é pequeno, mas brigou como se pagasse aluguel na represa!",tilapia:"Tilápia na linha! Hoje a panela vai ter que esperar: aqui é pesque e solte!",piau:"Olha o piau! Veio listrado e cheio de atitude!",pacu:"Esse pacu puxou com força de quem não queria aparecer na foto!",traira:"A traíra tentou fazer jus ao nome, mas hoje não escapou!",curimbata:"Curimbatá na mão! Nadou muito e perdeu no argumento!",carpa:"Essa carpa tem tamanho de quem conhece todos os cantos da represa!",jundia:"Jundiá fisgado! O bigode chegou antes do resto!",pintado:"Um pintado desses até parece que saiu arrumado para a foto!",corvina:"A corvina veio conferir quem estava fazendo barulho na água!",tucunare:"Tucunaré-amarelo: bonito, bravo e completamente sem paciência!",tucunare_azulao:"Azulão na linha! Esse fez a vara pedir reforço!",tucunare_vermelho:"Tucunaré-vermelho! Foi pesca ou cabo de guerra?"},CHANCE_LABEL={COMUM:"Comum",INCOMUM:"Incomum",RARO:"Raro",ÉPICO:"Épico",LENDÁRIO:"Lendário"};
